CREATE TABLE "commercial_identity_snapshots" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "commercial_identity_snapshots_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"product_id" integer NOT NULL,
	"sale_id" integer,
	"order_id" integer,
	"movement_id" integer,
	"delivery_quote_item_id" integer,
	"version" integer DEFAULT 1 NOT NULL,
	"origin" varchar(24) NOT NULL,
	"identity" jsonb NOT NULL,
	"captured_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "identity_snapshot_subject_check" CHECK (num_nonnulls("commercial_identity_snapshots"."sale_id","commercial_identity_snapshots"."order_id","commercial_identity_snapshots"."movement_id","commercial_identity_snapshots"."delivery_quote_item_id")=1),
	CONSTRAINT "identity_snapshot_format_check" CHECK ("commercial_identity_snapshots"."version"=1 and "commercial_identity_snapshots"."origin" in ('ORIGINAL','LEGACY_REFERENCE','LEGACY_PARTIAL') and coalesce(jsonb_typeof("commercial_identity_snapshots"."identity"->'name')='string' and jsonb_typeof("commercial_identity_snapshots"."identity"->'unitMeasure')='string' and jsonb_typeof("commercial_identity_snapshots"."identity"->'category')='object',false))
);
