CREATE FUNCTION fyf_record_commercial_identity() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE captured jsonb;
BEGIN
  captured:=fyf_capture_commercial_identity(NEW.product_id);
  IF captured IS NULL THEN RAISE EXCEPTION 'Product identity is unavailable' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='sale_details' THEN
    INSERT INTO commercial_identity_snapshots(product_id,sale_id,origin,identity) VALUES(NEW.product_id,NEW.sale_id,'ORIGINAL',captured);
  ELSIF TG_TABLE_NAME='online_order_items' THEN
    INSERT INTO commercial_identity_snapshots(product_id,order_id,origin,identity) VALUES(NEW.product_id,NEW.order_id,'ORIGINAL',captured);
  ELSIF TG_TABLE_NAME='inventory_movements' THEN
    INSERT INTO commercial_identity_snapshots(product_id,movement_id,origin,identity) VALUES(NEW.product_id,NEW.id,'ORIGINAL',captured);
  ELSIF TG_TABLE_NAME='delivery_quote_items' THEN
    INSERT INTO commercial_identity_snapshots(product_id,delivery_quote_item_id,origin,identity)
      VALUES(NEW.product_id,NEW.id,'ORIGINAL',captured || jsonb_build_object('name',NEW.product_name,'unitMeasure',NEW.unit_measure));
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER sale_identity_capture AFTER INSERT ON sale_details FOR EACH ROW EXECUTE FUNCTION fyf_record_commercial_identity();
--> statement-breakpoint
