CREATE FUNCTION fyf_guard_commercial_identity() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE subject_product integer; expected jsonb;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Commercial identity snapshots are immutable' USING ERRCODE='23514'; END IF;
  IF pg_trigger_depth()<2 OR NEW.origin<>'ORIGINAL' OR NEW.version<>1 THEN
    RAISE EXCEPTION 'Identity captures must originate from their commercial operation' USING ERRCODE='23514';
  END IF;
  expected:=fyf_capture_commercial_identity(NEW.product_id);
  IF NEW.movement_id IS NOT NULL THEN SELECT product_id INTO subject_product FROM inventory_movements WHERE id=NEW.movement_id;
  ELSIF NEW.delivery_quote_item_id IS NOT NULL THEN
    SELECT product_id,expected || jsonb_build_object('name',product_name,'unitMeasure',unit_measure)
      INTO subject_product,expected FROM delivery_quote_items WHERE id=NEW.delivery_quote_item_id;
  ELSE subject_product:=NEW.product_id; END IF;
  IF subject_product IS DISTINCT FROM NEW.product_id OR expected IS NULL OR NEW.identity IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'Identity capture does not match its source' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER commercial_identity_guard BEFORE INSERT OR UPDATE OR DELETE ON commercial_identity_snapshots
  FOR EACH ROW EXECUTE FUNCTION fyf_guard_commercial_identity();
--> statement-breakpoint
CREATE TRIGGER commercial_identity_no_truncate BEFORE TRUNCATE ON commercial_identity_snapshots
  FOR EACH STATEMENT EXECUTE FUNCTION fyf_guard_commercial_identity();
--> statement-breakpoint
CREATE FUNCTION fyf_preserve_commercial_line() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE before_row jsonb; after_row jsonb;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Historical commercial lines are retained' USING ERRCODE='23514'; END IF;
  before_row:=to_jsonb(OLD)-'updated_at'; after_row:=to_jsonb(NEW)-'updated_at';
  IF TG_TABLE_NAME='sale_details' THEN before_row:=before_row-'returned_quantity'; after_row:=after_row-'returned_quantity'; END IF;
  IF before_row IS DISTINCT FROM after_row THEN
    RAISE EXCEPTION 'Original commercial line data cannot change' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER sale_line_history_guard BEFORE UPDATE OR DELETE ON sale_details FOR EACH ROW EXECUTE FUNCTION fyf_preserve_commercial_line();
--> statement-breakpoint
CREATE TRIGGER order_line_history_guard BEFORE UPDATE OR DELETE ON online_order_items FOR EACH ROW EXECUTE FUNCTION fyf_preserve_commercial_line();
--> statement-breakpoint
CREATE TRIGGER movement_line_history_guard BEFORE UPDATE OR DELETE ON inventory_movements FOR EACH ROW EXECUTE FUNCTION fyf_preserve_commercial_line();
